package com.simpissuehub.api;
import com.simpissuehub.domain.*; import com.simpissuehub.repository.*; import com.simpissuehub.application.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.data.domain.Sort; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@RestController @RequestMapping("/api/v1/categories")
public class IssueCategoryController { private final IssueCategoryRepository categories; private final IssueRepository issues; private final AuthorizationService authorization; private final CurrentUserService identity; private final AuditService audit; public IssueCategoryController(IssueCategoryRepository c,IssueRepository issues,AuthorizationService a,CurrentUserService i,AuditService s){categories=c;this.issues=issues;authorization=a;identity=i;audit=s;}
 @GetMapping public List<CategoryView> list(){return categories.findAll(Sort.by("name")).stream().map(c->new CategoryView(c.id,c.name,categories.countOpenIssues(c.name))).toList();}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public CategoryView create(@Valid @RequestBody CategoryRequest r){User u=authorization.requireAdmin(identity.require()); String n=r.name().trim(); if(categories.findByName(n).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"服务器名称已存在"); IssueCategory c=new IssueCategory();c.name=n;c=categories.save(c);audit.record(u,"CATEGORY_CREATED","CATEGORY",c.id,"创建服务器 "+n);return new CategoryView(c.id,c.name,0);}
 @PatchMapping("/{id}") @Transactional public CategoryView rename(@PathVariable Long id,@Valid @RequestBody CategoryRequest r){User u=authorization.requireAdmin(identity.require()); IssueCategory c=categories.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"服务器不存在")); String n=r.name().trim(); if(categories.findByName(n).filter(x->!x.id.equals(id)).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"服务器名称已存在"); String old=c.name; issues.renameCategory(old,n); c.name=n; c=categories.save(c); audit.record(u,"CATEGORY_RENAMED","CATEGORY",id,old+" -> "+n); return new CategoryView(c.id,c.name,categories.countOpenIssues(c.name));}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){User u=authorization.requireAdmin(identity.require()); IssueCategory c=categories.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"服务器不存在")); if(categories.countIssues(c.name)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"服务器仍被反馈使用，无法删除");categories.delete(c);audit.record(u,"CATEGORY_DELETED","CATEGORY",id,"删除服务器 "+c.name);}
 public record CategoryView(Long id,String name,long issueCount){} public record CategoryRequest(@NotBlank @Size(max=32) String name){}
}
